from pathlib import Path
import sys,json,subprocess,time,hashlib
p=Path(__file__).resolve().parent;sys.path.insert(0,str(p));import transport as n
r=n.execute(r'''$ErrorActionPreference='Stop';$r='C:\OttrinOrdinaryQA';$owner=Get-Content "$r\OWNER.json" -Raw|ConvertFrom-Json;$baseline=Get-Content "$r\BASELINE.json" -Raw|ConvertFrom-Json;$user=Get-LocalUser -Name $owner.name;if($user.SID.Value-ne$owner.sid-or$user.Description-ne$owner.description){throw 'Owned account identity changed'};$result=Get-Content "$r\results\limited-direct-RESULT.json" -Raw|ConvertFrom-Json;if($result.status-ne'pass'-or$result.user-ne$owner.sid-or$result.administrator){throw 'Native acceptance mismatch'};$live=@(Get-CimInstance Win32_Process|Where-Object {($_.ExecutablePath-and$_.ExecutablePath.StartsWith($r+'\',[StringComparison]::OrdinalIgnoreCase))-or($_.CommandLine-and$_.CommandLine.Contains($r+'\actor.ps1'))});if($live.Count){throw 'Owned process still live'};$profile=Get-CimInstance Win32_UserProfile|Where-Object {$_.SID-eq$owner.sid};if($profile){if($profile.Loaded){throw 'Owned profile is loaded; inspect before cleanup'};$profile|Remove-CimInstance};Remove-LocalUser -Name $owner.name;$afterProfiles=@(Get-CimInstance Win32_UserProfile|ForEach-Object {$_.SID+'|'+$_.LocalPath}|Sort-Object);$beforeProfiles=@($baseline.profiles|ForEach-Object {$_.SID+'|'+$_.LocalPath}|Sort-Object);if(Compare-Object $beforeProfiles $afterProfiles){throw 'Original profile bindings changed'};$afterDisks=@(Get-Disk|ForEach-Object {($_.Number.ToString())+'|'+$_.UniqueId+'|'+$_.Size}|Sort-Object);$beforeDisks=@($baseline.disks|ForEach-Object {($_.Number.ToString())+'|'+$_.UniqueId+'|'+$_.Size}|Sort-Object);if(Compare-Object $beforeDisks $afterDisks){throw 'Disk bindings changed'};Remove-Item $r -Recurse -Force;if(Test-Path $r){throw 'Fixture remains'};@{status='pass';ownedAccountRemoved=$true;profileLoadRequested=$false;ownedProfileWasCreated=[bool]$profile;originalProfileBindingsPreserved=$true;disksPreserved=$true;ownedRootRemoved=$true;ownedProcesses=0;scope='No scheduled task, machine/user execution-policy change, stored credential, user logon setting or original profile changes'}|ConvertTo-Json''')
(p/'TEARDOWN_GUEST.json').write_text(r['out-data'])
try:n.qga('guest-shutdown',{'mode':'powerdown'})
except RuntimeError as e:(p/'shutdown-observation.txt').write_text(str(e)+'\n')
for attempt in range(60):
 state=subprocess.check_output(['virsh','-c','qemu:///system','domstate',n.guest.DOMAIN]).decode().strip()
 if state=='shut off':break
 time.sleep(.5)
assert state=='shut off',state
xml=subprocess.check_output(['virsh','-c','qemu:///system','dumpxml',n.guest.DOMAIN,'--inactive']);assert hashlib.sha256(xml).hexdigest()==json.loads((p/'OWNER.json').read_text())['definition_sha256']
(p/'TEARDOWN.json').write_text(json.dumps({'status':'pass','guest_off':True,'definition_unchanged':True,'guest_cleanup':'TEARDOWN_GUEST.json','owned_host_transfer_directories_removed':not any((p.parents[1]/'packaging-tmp').glob('ordinary-native-transfer-*')),'current_packages_and_source_caches_preserved':True},indent=2)+'\n');print('Scoped account, all fixtures and guest activity removed; original bindings preserved.')
